import{scanSystems,loadMappingIfNeeded,buildGeoForOptIn,buildGraphFromSystems,finalizeSeed}from"./pipeline.min.js";const log=msg=>self.postMessage({type:"log",msg});let scanned=null;let mosaicOptIn=false;self.onmessage=async e=>{try{if(!e.data.phase){await handleFiles(e.data.files,e.data.mapping)}else if(e.data.phase==="geo"){await handleGeo(e.data.geoOptIn,e.data.mosaicOptIn)}else if(e.data.phase==="confirm"){await handleConfirm(e.data.beats)}}catch(err){self.postMessage({type:"error",msg:String(err?.message??err)})}};async function handleFiles(rawFiles,obfuscationMapping){const files=rawFiles.map(f=>({name:f.name,bytes:new Uint8Array(f.buffer)}));const digests=[];for(const f of files){const h=await crypto.subtle.digest("SHA-256",f.bytes);digests.push({name:f.name,sha256:[...new Uint8Array(h)].map(b=>b.toString(16).padStart(2,"0")).join("")})}const mapping=await loadMappingIfNeeded(files,{log,loadMappingJson:async()=>obfuscationMapping});const{systems,playerStates,errors,undated,rejectedCount}=scanSystems(files,{log,mapping});scanned={systems,playerStates,digests};self.postMessage({type:"scanned",systemCount:systems.length,undatedCount:undated.length,rejectedCount,errors})}async function handleGeo(geoOptIn,wantsMosaic){mosaicOptIn=!!wantsMosaic;const{systems,playerStates,digests}=scanned;if(geoOptIn){const{geo,post,postJson}=await buildGeoForOptIn({systems},{log});self.postMessage({type:"geo",geo,post,postJson})}else{self.postMessage({type:"geo",skipped:true})}const{report,graph}=buildGraphFromSystems({systems,playerStates},{log});self.postMessage({type:"graph",report,graph,digests})}async function handleConfirm(beats){const{seed,destroyKey}=await finalizeSeed(beats,{mosaicPublic:mosaicOptIn,log});self.postMessage({type:"result",seed,destroyKey})}
